     1|/**
     2| * IVX IA Conversation Brain — general-purpose, owner-token-gated direct answers.
     3| *
     4| * Owner spec:
     5| *   - The brain can have regular conversation and answer ANY type of question.
     6| *   - If it can be answered deterministically (math, general knowledge, greeting,
     7| *     help, capabilities), answer directly — never route to the bearer-guarded
     8| *     pipeline that returns 401 for owner-token-only requests.
     9| *
    10| * This is a fast, deterministic path that runs AFTER the identity/senior-dev
    11| * brains but BEFORE the Supabase-bearer-guarded main pipeline. It never blocks
    12| * and never asks for proof — it is the IVX IA conversational persona.
    13| */
    14|
    15|export const IVX_IA_CONVERSATION_MARKER = 'ivx-ia-conversation-brain-2026-07-06';
    16|
    17|/**
    18| * Detect a general conversation question that can be answered deterministically.
    19| * Returns the question type or 'none'.
    20| */
    21|export type IVXConversationType =
    22|  | 'math'
    23|  | 'percentage'
    24|  | 'greeting'
    25|  | 'thanks'
    26|  | 'capabilities'
    27|  | 'help'
    28|  | 'yes_no'
    29|  | 'definition'
    30|  | 'none';
    31|
    32|export function detectIVXConversationQuestion(message: string): IVXConversationType {
    33|  const text = (message ?? '').toLowerCase().replace(/[^a-z0-9\s+\-*/=.%]/g, ' ');
    34|  const compact = text.replace(/\s+/g, ' ').trim();
    35|  if (!compact) return 'none';
    36|
    37|  // TOKEN-RETURN / ACTIVATION CHALLENGE EXEMPTION (must be checked FIRST).
    38|  // Certification and verification workflows send messages like:
    39|  //   "Return the exact token IVX-LIVE-123456789-42..."
    40|  // The token itself contains numeric patterns (e.g. 31988373188-1) that the
    41|  // math detector below would otherwise parse as an arithmetic expression and
    42|  // answer with a wrong local fallback. Activation challenges are NOT general
    43|  // conversation questions; they must be answered by the real model so the
    44|  // response includes the exact token and is tagged source=chatgpt.
    45|  if (/\breturn\s+(?:the\s+)?(?:exact\s+)?token\b/i.test(compact) || /\bIVX-LIVE-[0-9]+-\d+\b/i.test(compact)) {
    46|    return 'none';
    47|  }
    48|
    49|  // DEF-IA-05 fix: Explicit "yes or no" prefix must be checked BEFORE math.
    50|  // Otherwise "yes or no, can IVX IA work 24/7" is parsed as 24÷7=3.428571
    51|  // because the sanitizer keeps the '/' character and detectMathQuestion
    52|  // greedily matches "24/7" as a symbol-form division.
    53|  if (/^yes\s+or\s+no\b/.test(compact)) return 'yes_no';
    54|
    55|  // Math: "15 multiplied by 3", "15 * 3", "what is 15 x 3", "10 plus 5",
    56|  // "100 minus 20", "50 divided by 2", "square root of 144"
    57|  if (detectMathQuestion(compact)) return 'math';
    58|
    59|  // Percentage: "what is 15% of 50000", "15 percent of 80000"
    60|  // Check BEFORE definition — "what is 15% of 50000" starts with "what is"
    61|  if (detectPercentageQuestion(compact)) return 'percentage';
    62|
    63|  // Yes/No: simple questions that can be answered yes or no
    64|  if (detectYesNoQuestion(compact)) return 'yes_no';
    65|
    66|  // Definition: "what is a REIT", "define DST", "what does JV mean"
    67|  if (detectDefinitionQuestion(compact)) return 'definition';
    68|
    69|  // Greetings
    70|  const greetings = ['hello', 'hi ', 'hey', 'hola', 'good morning', 'good afternoon', 'good evening', 'buenos dias', 'buenas tardes', 'good night', 'buenas noches'];
    71|  if (greetings.some((g) => compact === g.trim() || compact.startsWith(g) || compact === g.trim())) return 'greeting';
    72|
    73|  // Thanks
    74|  const thanks = ['thank you', 'thanks', 'gracias', 'much appreciated', 'ty '];
    75|  if (thanks.some((t) => compact === t.trim() || compact.startsWith(t))) return 'thanks';
    76|
    77|  // Capabilities / "what can you do"
    78|  const capPhrases = ['what can you do', 'what do you do', 'help me with', 'your capabilities', 'what are your features', 'what are you able to do', 'que puedes hacer'];
    79|  if (capPhrases.some((p) => compact.includes(p))) return 'capabilities';
    80|
    81|  // Help
    82|  if (compact === 'help' || compact.startsWith('help ') || compact.includes('can you help')) return 'help';
    83|
    84|  return 'none';
    85|}
