    87|/**
    88| * Detect and evaluate a math question.
    89| * Handles: plus, minus, multiplied by, times, divided by, x, *, /, +, -, sqrt.
    90| */
    91|function detectMathQuestion(compact: string): boolean {
    92|  // Exclude 24/7 idiom for exclusion from math parsing
    93|  if (/\b(work|operate|run|available)\b.*\b(24\s*7|24\/7)\b|\b(24\s*7|24\/7)\b.*\b(work|operate|run|available)\b/.test(compact)) return false;
    94|  // Word-form arithmetic
    95|  const wordMath = /\b(\d+(?:\.\d+)?)\s+(plus|minus|multiplied by|times|divided by|added to|subtracted from)\s+(\d+(?:\.\d+)?)/;
    96|  if (wordMath.test(compact)) return true;
    97|  // Symbol-form arithmetic (single regex test — removed redundant double check)
    98|  const symMath = /\b(\d+(?:\.\d+)?)\s*[+\-*/x]\s*(\d+(?:\.\d+)?)/;
    99|  if (symMath.test(compact)) return true;
   100|  // "what is N op N"
   101|  if (/\bwhat is\s+/.test(compact) && wordMath.test(compact)) return true;
   102|  // square root
   103|  if (/\b(square root|sqrt)\s+of\s+\d+/.test(compact)) return true;
   104|  return false;
   105|}
