   107|/**
   108| * Detect a percentage question: "what is 15% of 50000", "15 percent of 80000".
   109| */
   110|function detectPercentageQuestion(compact: string): boolean {
   111|  return /\b\d+(?:\.\d+)?\s*(%|percent)\s+of\s+\d+/i.test(compact);
   112|}
   113|
   114|/**
   115| * Evaluate a percentage expression from natural language.
   116| */
   117|function evaluatePercentageQuestion(message: string): number | null {
   118|  // Strip currency symbols and commas BEFORE sanitizing so numbers like
   119|  // "$240,000" are preserved as "240000" not broken into "240 000".
   120|  const text = (message ?? '')
   121|    .toLowerCase()
   122|    .replace(/[$,€£¥]/g, '')
   123|    .replace(/[^a-z0-9\s%.]/g, ' ')
   124|    .replace(/\s+/g, ' ')
   125|    .trim();
   126|  const match = text.match(/(\d+(?:\.\d+)?)\s*(?:%|percent)\s+of\s+(\d+(?:\.\d+)?)/);
   127|  if (!match) return null;
   128|  const pct = parseFloat(match[1]);
   129|  const base = parseFloat(match[2]);
   130|  if (!isFinite(pct) || !isFinite(base)) return null;
   131|  return (pct / 100) * base;
   132|}
