   134|/**
   135| * Detect a yes/no question that can be answered deterministically.
   136| */
   137|function detectYesNoQuestion(compact: string): boolean {
   138|  // "is ivx a reit", "can i invest", "does ivx offer tokenization"
   139|  if (/^(is|are|can|do|does|will|should|has|have)\b/.test(compact) && compact.length < 120) return true;
   140|  return false;
