   143|/**
   144| * Answer a yes/no question about IVX.
   145| */
   146|function answerYesNoQuestion(message: string): string | null {
   147|  const text = (message ?? '').toLowerCase().replace(/[^a-z0-9\s]/g, ' ').replace(/\s+/g, ' ').trim();
   148|  // IVX-specific yes/no answers
   149|  if (/\b(is|are)\b.*\b(reit|dst|1031)\b/.test(text)) {
   150|    return 'No, IVX Holdings is not a REIT or DST. IVX is a real-estate joint-venture platform that offers fractional ownership in specific projects, not a traded trust entity.';
   151|  }
   152|  if (/\bcan\b.*\b(invest|buy|participate)\b/.test(text)) {
   153|    return 'Yes, you can invest through IVX Holdings by reviewing available projects and participating with fractional ownership. Visit ivxholding.com to see current offerings.';
   154|  }
   155|  if (/\b(does|do)\b.*\b(tokeniz|wallet|withdraw|wire)/.test(text)) {
   156|    return 'Yes, IVX Holdings supports tokenization, wallet management, withdrawals, and wire transfers for qualified investors.';
   157|  }
   158|  if (/\b(is|are)\b.*\b(legit|safe|secure|regulated)\b/.test(text)) {
   159|    return 'Yes, IVX Holdings operates with proper corporate structure and compliance. All investments are documented through formal JV agreements.';
   160|  }
   161|  // DEF-IA-05 fix: "can IVX IA work 24/7" — the '24/7' was stripped to '24 7'
   162|  // by the sanitizer; match on 'work' + '24 7' or '24 7' context.
   163|  if (/\bcan\b.*\b(work|operate|run|function)\b.*\b(24\s*7|around the clock|all day|nonstop|continuously)\b/.test(text)) {
   164|    return 'Yes, IVX IA can work 24/7. The AI brain is always available to answer questions, analyze deals, and assist investors — no business hours required.';
   165|  }
   166|  // Generic fallback — don't guess, route to AI
   167|  return null;
   168|}
