   170|/**
   171| * Detect a definition question: "what is a REIT", "define DST", "what does JV mean".
   172| */
   173|function detectDefinitionQuestion(compact: string): boolean {
   174|  if (/^(what is|what are|what does|define|explain)\b/.test(compact) && compact.length < 150) return true;
   175|  return false;
