   208|function evaluateMathQuestion(message: string): number | null {
   209|  // Strip currency symbols and commas before sanitizing so numbers like
   210|  // "$240,000 + $120,000" are preserved as "240000 + 120000".
   211|  const text = (message ?? '').toLowerCase().replace(/[$,€£¥]/g, '').replace(/[^a-z0-9\s+\-*/=.]/g, ' ').replace(/\s+/g, ' ').trim();
   212|  // square root
   213|  const sqrtMatch = text.match(/(?:square root|sqrt)\s+of\s+(\d+(?:\.\d+)?)/);
   214|  if (sqrtMatch) {
   215|    const n = parseFloat(sqrtMatch[1]);
   216|    return Math.sqrt(n);
   217|  }
   218|  // word-form
   219|  const wordMatch = text.match(/(\d+(?:\.\d+)?)\s+(plus|minus|multiplied by|times|divided by|added to|subtracted from)\s+(\d+(?:\.\d+)?)/);
   220|  if (wordMatch) {
   221|    const a = parseFloat(wordMatch[1]);
   222|    const op = wordMatch[2];
   223|    const b = parseFloat(wordMatch[3]);
   224|    switch (op) {
   225|      case 'plus': case 'added to': return a + b;
   226|      case 'minus': case 'subtracted from': return op === 'subtracted from' ? b - a : a - b;
   227|      case 'multiplied by': case 'times': return a * b;
   228|      case 'divided by': return b === 0 ? null : a / b;
   229|    }
   230|  }
   231|  // symbol-form: "what is 15 x 3" / "15 * 3" / "10 + 5"
   232|  const symMatch = text.match(/(\d+(?:\.\d+)?)\s*([+\-*/x])\s*(\d+(?:\.\d+)?)/);
   233|  if (symMatch) {
   234|    const a = parseFloat(symMatch[1]);
   235|    const op = symMatch[2];
   236|    const b = parseFloat(symMatch[3]);
   237|    switch (op) {
   238|      case '+': return a + b;
   239|      case '-': return a - b;
   240|      case '*': case 'x': return a * b;
   241|      case '/': return b === 0 ? null : a / b;
   242|    }
   243|  }
   244|  return null;
